package agentprotocol

import (
	"errors"
	"strings"

	"github.com/eeyung1/multi-agent-orchestrator/internal/planning"
)

const PlanningCapability Capability = "planning"

// PlannerCorrelation is generated by Go. Echoing it is necessary, never
// sufficient, for accepting a response from the exact selected bound session.
type PlannerCorrelation struct {
	RunID     string `json:"run_id"`
	BindingID string `json:"binding_id"`
	RequestID string `json:"request_id"`
}

func (c PlannerCorrelation) Validate() error {
	for _, v := range []string{c.RunID, c.BindingID, c.RequestID} {
		if identifier("Planner correlation", v) != nil {
			return errors.New("invalid Planner correlation")
		}
	}
	return nil
}

type PlanningRequest struct {
	Correlation PlannerCorrelation `json:"correlation"`
	Request     planning.Request   `json:"request"`
}

func (r PlanningRequest) Validate() error {
	if err := r.Correlation.Validate(); err != nil {
		return err
	}
	if strings.TrimSpace(r.Request.Objective) == "" || r.Request.Recon.Workspace == "" || r.Request.Recon.Head == "" || len(r.Request.Capabilities) == 0 || len(r.Request.Validators) == 0 || len(r.Request.AllowedScopes) == 0 {
		return errors.New("incomplete Planner request")
	}
	return nil
}

type PlanningResponse struct {
	Correlation PlannerCorrelation `json:"correlation"`
	Proposal    planning.Proposal  `json:"proposal"`
}

func (r PlanningResponse) Validate() error {
	if err := r.Correlation.Validate(); err != nil {
		return err
	}
	return r.Proposal.Validate()
}
